<script setup lang="ts">
import {computed,ref,watch} from 'vue'
const props=defineProps<{value:string;sample?:string}>(),emit=defineEmits<{apply:[string];close:[]}>(),draft=ref(props.value),hue=ref(0),saturation=ref(0),brightness=ref(0)
function parse(hex:string){const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255),max=Math.max(...rgb),min=Math.min(...rgb),delta=max-min;hue.value=delta===0?0:(((max===rgb[0]?(rgb[1]-rgb[2])/delta:max===rgb[1]?(rgb[2]-rgb[0])/delta+2:(rgb[0]-rgb[1])/delta+4)*60+360)%360);saturation.value=max?delta/max:0;brightness.value=max}
parse(props.value)
function fromHSV(){const c=brightness.value*saturation.value,h=hue.value/60,x=c*(1-Math.abs(h%2-1)),m=brightness.value-c,rgb=h<1?[c,x,0]:h<2?[x,c,0]:h<3?[0,c,x]:h<4?[0,x,c]:h<5?[x,0,c]:[c,0,x];draft.value='#'+rgb.map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('')}
watch(()=>props.sample,value=>{if(value){draft.value=value;parse(value)}})
const rgb=computed(()=>[1,3,5].map(i=>parseInt(draft.value.slice(i,i+2),16)))
function setRGB(index:number,value:string){const values=[...rgb.value];values[index]=Math.max(0,Math.min(255,Math.round(Number(value)||0)));draft.value='#'+values.map(v=>v.toString(16).padStart(2,'0')).join('');parse(draft.value)}
function setHex(value:string){if(/^#?[a-f0-9]{6}$/i.test(value)){draft.value='#'+value.replace('#','').toLowerCase();parse(draft.value)}}
let dragging:HTMLElement|undefined
function point(event:PointerEvent){const target=event.currentTarget as HTMLElement,rect=target.getBoundingClientRect();saturation.value=Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width));brightness.value=1-Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height));fromHSV()}
function start(event:PointerEvent){dragging=event.currentTarget as HTMLElement;dragging.setPointerCapture(event.pointerId);point(event)}
function move(event:PointerEvent){if(dragging)point(event)}
function end(event:PointerEvent){if(dragging?.hasPointerCapture(event.pointerId))dragging.releasePointerCapture(event.pointerId);dragging=undefined}
</script>
<template><section class="color-picker-panel" role="dialog" aria-label="Color Picker"><strong>Color Picker</strong><div class="color-picker-body"><div class="sv" aria-label="Saturation and brightness" :style="{background:`linear-gradient(to top,black,transparent),linear-gradient(to right,white,hsl(${hue},100%,50%))`}" @pointerdown="start" @pointermove="move" @pointerup="end" @pointercancel="end"><span :style="{left:`${saturation*100}%`,top:`${(1-brightness)*100}%`}"/></div><label>Hue<input v-model.number="hue" type="range" min="0" max="360" aria-label="Color hue" @input="fromHSV"/></label><div class="color-picker-fields"><div class="previews"><span :style="{background:draft}" title="New"/><span :style="{background:value}" title="Current"/></div><label v-for="(channel,i) in ['R','G','B']">{{channel}}<input :value="rgb[i]" type="number" min="0" max="255" :aria-label="`Color ${channel}`" @change="setRGB(i,($event.target as HTMLInputElement).value)"/></label><label>Hex<input :value="draft" aria-label="Color hex" @change="setHex(($event.target as HTMLInputElement).value)"/></label><button @click="emit('apply',draft)">OK</button><button @click="emit('close')">Cancel</button></div></div><small>Click the canvas to sample a color.</small></section></template>
<style scoped>.color-picker-panel{position:absolute;z-index:30;right:355px;top:145px;background:#292929;border:1px solid #484848;border-radius:8px;padding:18px;box-shadow:0 8px 30px #0008;color:#ddd}.color-picker-body{display:flex;gap:12px;margin:14px 0}.sv{position:relative;width:220px;height:220px;touch-action:none;cursor:crosshair}.sv span{position:absolute;width:10px;height:10px;border:1px solid white;box-shadow:0 0 0 1px black;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}.color-picker-fields{display:flex;flex-direction:column;gap:8px;width:130px}.color-picker-fields label{display:flex;gap:8px;align-items:center}.color-picker-fields input{min-width:0;width:90px;color:#ddd;background:#191919;border:1px solid #555;border-radius:4px;padding:3px}.previews{display:flex;height:28px}.previews span{flex:1;border:1px solid #555}small{color:#aaa}</style>
